// SPDX-License-Identifier: Apache-2.0
use portable_pty::{native_pty_system, CommandBuilder, MasterPty, PtySize, Child};
use serde::Serialize;
use std::{collections::HashMap, io::{Read, Write}, sync::{atomic::{AtomicU64, Ordering}, Mutex}};
use tauri::{Emitter, State};
use super::{connection, request, Desktop};
struct Session { master: Box<dyn MasterPty + Send>, writer: Box<dyn Write + Send>, child: Box<dyn Child + Send + Sync> }
#[derive(Default)]
pub struct Terminals { sessions: Mutex<HashMap<String, Session>>, next: AtomicU64 }
impl Terminals {
    pub fn close_all(&self) { if let Ok(mut sessions) = self.sessions.lock() { for (_, mut s) in sessions.drain() { let _ = s.child.kill(); } } }
}
#[derive(Clone, Serialize)]
struct Output { id: String, text: String }
fn decode_output(pending: &mut Vec<u8>, eof: bool) -> String {
    let mut text = String::new();
    loop {
        match std::str::from_utf8(pending) {
            Ok(s) => { text.push_str(s); pending.clear(); break; }
            Err(e) => {
                let valid = e.valid_up_to();
                text.push_str(&String::from_utf8_lossy(&pending[..valid]));
                pending.drain(..valid);
                if let Some(invalid) = e.error_len() { text.push('�'); pending.drain(..invalid); }
                else { if eof { text.push_str(&String::from_utf8_lossy(pending)); pending.clear(); } break; }
            }
        }
    }
    text
}
#[tauri::command]
pub async fn terminal_open(app: tauri::AppHandle, state: State<'_, Desktop>, kind: String, agent_id: Option<String>, assignment_id: Option<String>) -> Result<String, String> {
    let live = request(&connection(&state)?, "/api/state", "GET", None).await?;
    let s = &live["state"];
    let cwd = if let Some(id) = assignment_id {
        s["assignments"][&id]["worktree"].as_str().ok_or("Assignment has no worktree")?
    } else { s["project"]["repo"].as_str().ok_or("Project missing")? };
    let mut cmd;
    if kind == "login" {
        let id = agent_id.ok_or("Choose an agent")?;
        let a = &s["agents"][&id];
        let binary = a["binary"]["path"].as_str().or_else(|| a["config"]["binary"].as_str()).ok_or("Probe this agent to locate its official CLI")?;
        cmd = CommandBuilder::new(binary);
        match a["config"]["adapter"].as_str().unwrap_or("") {
            "codex-cli" => cmd.arg("login"),
            "claude-headless" => cmd.args(["auth", "login"]),
            "cursor-agent-cli" => cmd.arg("login"),
            _ => return Err("This adapter has no native login command".into()),
        }
    } else if kind == "shell" {
        #[cfg(unix)] { cmd = CommandBuilder::new(std::env::var("SHELL").unwrap_or("/bin/zsh".into())); cmd.arg("-l"); }
        #[cfg(windows)] { cmd = CommandBuilder::new("powershell.exe"); }
    } else { return Err("Unsupported terminal type".into()); }
    cmd.cwd(cwd);
    cmd.env("TERM", "xterm-256color");
    // The control center never gives API keys to a subscription login terminal.
    for k in ["ANTHROPIC_API_KEY", "OPENAI_API_KEY", "CODEX_API_KEY", "OPENROUTER_API_KEY", "CURSOR_API_KEY"] { cmd.env_remove(k); }
    let pair = native_pty_system().openpty(PtySize { rows: 28, cols: 100, pixel_width: 0, pixel_height: 0 }).map_err(|e| e.to_string())?;
    let child = pair.slave.spawn_command(cmd).map_err(|e| e.to_string())?;
    drop(pair.slave);
    let reader = pair.master.try_clone_reader().map_err(|e| e.to_string())?;
    let writer = pair.master.take_writer().map_err(|e| e.to_string())?;
    let id = format!("terminal-{}", state.terminals.next.fetch_add(1, Ordering::Relaxed));
    state.terminals.sessions.lock().map_err(|_| "Terminal state unavailable")?.insert(id.clone(), Session { master: pair.master, writer, child });
    let thread_id = id.clone();
    std::thread::spawn(move || {
        let mut reader = reader;
        let mut buf = [0; 8192];
        let mut pending = Vec::new();
        loop {
            match reader.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    pending.extend_from_slice(&buf[..n]);
                    let text = decode_output(&mut pending, false);
                    if !text.is_empty() { let _ = app.emit("terminal-output", Output { id: thread_id.clone(), text }); }
                }
            }
        }
        let tail = decode_output(&mut pending, true);
        let _ = app.emit("terminal-output", Output { id: thread_id, text: format!("{tail}\r\n[terminal exited]\r\n") });
    });
    Ok(id)
}
#[tauri::command]
pub fn terminal_write(state: State<'_, Desktop>, id: String, text: String) -> Result<(), String> {
    if text.len() > 64_000 { return Err("Input too large".into()); }
    let mut sessions = state.terminals.sessions.lock().map_err(|_| "Terminal state unavailable")?;
    let s = sessions.get_mut(&id).ok_or("Terminal closed")?;
    s.writer.write_all(text.as_bytes()).and_then(|_| s.writer.flush()).map_err(|e| e.to_string())
}
#[tauri::command]
pub fn terminal_resize(state: State<'_, Desktop>, id: String, rows: u16, cols: u16) -> Result<(), String> {
    state.terminals.sessions.lock().map_err(|_| "Terminal state unavailable")?.get(&id).ok_or("Terminal closed")?.master.resize(PtySize { rows: rows.clamp(2, 200), cols: cols.clamp(2, 500), pixel_width: 0, pixel_height: 0 }).map_err(|e| e.to_string())
}
#[tauri::command]
pub fn terminal_close(state: State<'_, Desktop>, id: String) -> Result<(), String> {
    if let Some(mut s) = state.terminals.sessions.lock().map_err(|_| "Terminal state unavailable")?.remove(&id) { s.child.kill().map_err(|e| e.to_string())?; }
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test] fn output_survives_split_unicode_and_invalid_bytes() {
        let mut p = vec![b'a', 0xe2];
        assert_eq!(decode_output(&mut p, false), "a");
        p.extend_from_slice(&[0x9c, 0x93, 0xff, b'b']);
        assert_eq!(decode_output(&mut p, false), "✓�b");
        p.push(0xe2);
        assert_eq!(decode_output(&mut p, true), "�");
        assert!(p.is_empty());
    }
    #[test]
    #[cfg(unix)]
    fn real_pty_runs_and_resizes() {
        let pair = native_pty_system().openpty(PtySize { rows: 20, cols: 80, pixel_width: 0, pixel_height: 0 }).unwrap();
        pair.master.resize(PtySize { rows: 30, cols: 100, pixel_width: 0, pixel_height: 0 }).unwrap();
        assert_eq!(pair.master.get_size().unwrap().cols, 100);
        let mut command = CommandBuilder::new("/bin/sh");
        command.args(["-c", "printf '\\342\\234\\223\\n'"]);
        let mut child = pair.slave.spawn_command(command).unwrap();
        drop(pair.slave);
        let mut reader = pair.master.try_clone_reader().unwrap();
        // A PTY master can remain open after the child exits. Read the expected frame rather
        // than waiting for EOF on the terminal device.
        let mut bytes = [0; 5];
        reader.read_exact(&mut bytes).unwrap();
        assert_eq!(std::str::from_utf8(&bytes).unwrap(), "✓\r\n");
        assert!(child.wait().unwrap().success());
    }
}

// SPDX-License-Identifier: Apache-2.0
// Durable app-data locations. Logs and evidence must survive restarts, so temp dirs are refused.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export interface DataPaths {
  root: string;
  db: string;
  runs: string;
  worktrees: string;
  hooks: string;
  secrets: string;
  installToken: string;
}

export function defaultDataDir(): string {
  if (process.env.ACC_DATA_DIR) return path.resolve(process.env.ACC_DATA_DIR);
  const home = os.homedir();
  if (process.platform === 'darwin') return path.join(home, 'Library', 'Application Support', 'AgentControlCenter');
  if (process.platform === 'win32') return path.join(process.env.APPDATA ?? path.join(home, 'AppData', 'Roaming'), 'AgentControlCenter');
  return path.join(process.env.XDG_STATE_HOME ?? path.join(home, '.local', 'state'), 'agent-control-center');
}

function real(p: string): string {
  try {
    return fs.realpathSync(p);
  } catch {
    return path.resolve(p);
  }
}

export function isUnderTemp(dir: string): boolean {
  const target = real(dir);
  const temps = [os.tmpdir(), '/tmp', '/private/tmp', '/var/tmp', '/private/var/tmp', '/var/folders', '/private/var/folders'].map(real);
  return temps.some((t) => target === t || target.startsWith(t + path.sep));
}

export class TempDataDirError extends Error {}

export function resolveDataPaths(root = defaultDataDir(), opts: { allowTemp?: boolean } = {}): DataPaths {
  const allowTemp = opts.allowTemp ?? process.env.ACC_ALLOW_TEMP_DATA_DIR === '1';
  fs.mkdirSync(root, { recursive: true, mode: 0o700 });
  if (isUnderTemp(root) && !allowTemp) {
    throw new TempDataDirError(
      `Refusing to use ${root} for durable state: it is inside a temp directory that the OS wipes, which would lose run logs and evidence. Set ACC_DATA_DIR to a durable folder.`,
    );
  }
  const p: DataPaths = {
    root,
    db: path.join(root, 'acc.sqlite'),
    runs: path.join(root, 'runs'),
    worktrees: path.join(root, 'worktrees'),
    hooks: path.join(root, 'hooks'),
    secrets: path.join(root, 'secrets'),
    installToken: path.join(root, 'secrets', 'install-token'),
  };
  for (const d of [p.runs, p.worktrees, p.hooks]) fs.mkdirSync(d, { recursive: true, mode: 0o700 });
  fs.mkdirSync(p.secrets, { recursive: true, mode: 0o700 });
  fs.chmodSync(p.secrets, 0o700);
  return p;
}

export function expandHome(p: string): string {
  return p === '~' ? os.homedir() : p.startsWith('~/') ? path.join(os.homedir(), p.slice(2)) : p;
}

/** Write a file only the current user can read (tokens). */
export function writePrivate(file: string, content: string): void {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  fs.writeFileSync(file, content, { mode: 0o600 });
  fs.chmodSync(file, 0o600);
}

// SPDX-License-Identifier: Apache-2.0
import { HUMAN, newId, type Decision } from '@acc/core';
import { run, type ExecResult } from './exec.ts';
import type { Daemon } from './daemon.ts';
type DockerRun = (args: string[]) => Promise<ExecResult>;
export class ProjectDocker {
  readonly d: Daemon;
  readonly execute: DockerRun;
  constructor(d: Daemon, execute?: DockerRun) { this.d = d; this.execute = execute ?? (args => run('docker', args, { timeoutMs: 30000, maxBytes: 128000 })); }
  async list() {
    const project = this.d.config.project.docker_project ?? this.d.config.project.name;
    const r = await this.execute(['ps', '-a', '--filter', `label=com.docker.compose.project=${project}`, '--format', '{{json .}}']);
    if (r.code !== 0) return { available: false, project, containers: [], error: r.error ?? r.stderr.trim() };
    const containers = r.stdout.split('\n').filter(Boolean).map(line => JSON.parse(line) as { ID: string; Names: string; State: string; Status: string; Image: string });
    return { available: true, project, containers, error: null };
  }
  private async target(id: string) {
    if (!/^[a-f0-9]{12,64}$/.test(id)) throw new Error('Invalid container ID');
    const { containers } = await this.list();
    if (!containers.some(c => c.ID === id)) throw new Error('Container is outside this configured Compose project');
    return id;
  }
  async logs(id: string) {
    await this.target(id);
    const r = await this.execute(['logs', '--timestamps', '--tail', '300', id]);
    return { text: this.d.redactText(r.stdout + r.stderr), exitCode: r.code };
  }
  async request(id: string, action: string) {
    await this.target(id);
    if (!['start', 'stop', 'restart'].includes(action)) throw new Error('Unsupported Docker action');
    const decision: Decision = { id: newId('decision'), question: `Run docker ${action} ${id} in ${this.d.config.project.docker_project ?? this.d.config.project.name}?`, options: ['approve', 'deny'], recommendation: null, evidenceLinks: [], urgency: 'normal', irreversible: false, answer: null, answeredAt: null, channel: null, createdAt: this.d.nowIso() };
    this.d.commit([{ type: 'decision.created', actor: HUMAN, data: { decision } }], [], () => this.d.store.kvSet(`docker:${decision.id}`, JSON.stringify({ id, action, expires: Date.now() + 120000, consumed: false })));
    return { decision };
  }
  async resolve(decisionId: string, answer: string) {
    const raw = this.d.store.kvGet(`docker:${decisionId}`);
    const decision = this.d.state.decisions[decisionId];
    if (!raw || !decision || decision.answeredAt) throw new Error('Approval missing or already consumed');
    const a = JSON.parse(raw) as { id: string; action: string; expires: number; consumed: boolean };
    if (a.consumed || a.expires < Date.now()) throw new Error('Approval expired or consumed');
    if (!['approve', 'deny'].includes(answer)) throw new Error('Choose approve or deny');
    await this.target(a.id);
    // Re-check after await: simultaneous confirmations cannot execute the same approval twice.
    if (this.d.state.decisions[decisionId].answeredAt) throw new Error('Approval already consumed');
    this.d.commit([{ type: 'decision.answered', actor: HUMAN, data: { decisionId, answer, channel: 'dashboard' } }], [], () => this.d.store.kvSet(`docker:${decisionId}`, JSON.stringify({ ...a, consumed: true })));
    if (answer === 'deny') return { executed: false };
    const r = await this.execute([a.action, a.id]);
    this.d.commit([{ type: 'docker.action', actor: HUMAN, data: { decisionId, command: ['docker', a.action, a.id], exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr + (r.error ?? '')) } }]);
    return { executed: true, exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr) };
  }
}

// SPDX-License-Identifier: Apache-2.0
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { formatConfigError, parseConfig, type ControlCenterConfig } from '@acc/core';
import { expandHome } from './paths.ts';

export class ConfigError extends Error {}

export function findConfig(explicit?: string): string {
  const candidates = [explicit, process.env.ACC_CONFIG, path.resolve('control-center.yaml'), path.resolve('control-center.yml')].filter(Boolean) as string[];
  for (const c of candidates) if (fs.existsSync(c)) return path.resolve(c);
  throw new ConfigError(`No control-center.yaml found (looked at ${candidates.join(', ')}). Copy examples/control-center.yaml and edit it.`);
}

export function loadConfig(file: string): ControlCenterConfig {
  let raw: unknown;
  try {
    raw = YAML.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    throw new ConfigError(`${file}: ${(e as Error).message}`);
  }
  let cfg: ControlCenterConfig;
  try {
    cfg = parseConfig(raw);
  } catch (e) {
    throw new ConfigError(`${file} is invalid:\n${formatConfigError(e)}`);
  }
  const base = path.dirname(file);
  cfg.project.repo = path.resolve(base, expandHome(cfg.project.repo));
  for (const a of cfg.agents) if (a.binary) a.binary = path.resolve(base, expandHome(a.binary));
  return cfg;
}

// SPDX-License-Identifier: Apache-2.0
import { spawn } from 'node:child_process';

export interface ExecResult {
  code: number | null;
  stdout: string;
  stderr: string;
  timedOut: boolean;
  error?: string;
}

export interface ExecOptions {
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  input?: string;
  timeoutMs?: number;
  maxBytes?: number;
  signal?:AbortSignal;
}

/** Run a command without a shell. Never throws; inspect `code` / `error`. */
export function run(cmd: string, args: readonly string[], o: ExecOptions = {}): Promise<ExecResult> {
  return new Promise((resolve) => {
    const max = o.maxBytes ?? 8 * 1024 * 1024;
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    let settled = false;
    const done = (r: ExecResult) => {
      if (!settled) {
        settled = true;
        resolve(r);
      }
    };
    let child;
    try {
      child = spawn(cmd, args, { cwd: o.cwd, env: o.env ?? process.env, signal:o.signal, stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (e) {
      done({ code: null, stdout: '', stderr: '', timedOut: false, error: (e as Error).message });
      return;
    }
    const timer = o.timeoutMs
      ? setTimeout(() => {
          timedOut = true;
          child.kill('SIGKILL');
        }, o.timeoutMs)
      : null;
    child.stdout.on('data', (b: Buffer) => {
      if (stdout.length < max) stdout += b.toString('utf8');
    });
    child.stderr.on('data', (b: Buffer) => {
      if (stderr.length < max) stderr += b.toString('utf8');
    });
    child.on('error', (e) => {
      if (timer) clearTimeout(timer);
      done({ code: null, stdout, stderr, timedOut, error: e.message });
    });
    child.on('close', (code) => {
      if (timer) clearTimeout(timer);
      done({ code, stdout, stderr, timedOut });
    });
    child.stdin.on('error', () => {});
    if (o.input !== undefined) child.stdin.end(o.input);
    else child.stdin.end();
  });
}

/** Run through `sh -c` (for configured check commands like "npm test && npm run lint"). */
export function runShell(command: string, o: ExecOptions = {}): Promise<ExecResult> {
  return run('/bin/sh', ['-c', command], o);
}

