import { useEffect, useRef, useState } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { listen } from '@tauri-apps/api/event';
import { Terminal } from '@xterm/xterm';
import { FitAddon } from '@xterm/addon-fit';
import '@xterm/xterm/css/xterm.css';
export function NativeTerminal({ kind = 'shell', agentId, assignmentId }: { kind?: 'shell' | 'login'; agentId?: string; assignmentId?: string }) {
  const box = useRef<HTMLDivElement>(null);
  const [error, setError] = useState('');
  useEffect(() => {
    let disposed = false;
    let id: string | null = null;
    let unlisten: (() => void) | undefined;
    const early: { id: string; text: string }[] = [];
    const terminal = new Terminal({ cursorBlink: true, fontSize: 13, fontFamily: 'Menlo, monospace', scrollback: 10000, theme: { background: '#10151c', foreground: '#dde3ec' } });
    const fit = new FitAddon(); terminal.loadAddon(fit); terminal.open(box.current!); fit.fit();
    const resize = new ResizeObserver(() => { fit.fit(); if (id) void invoke('terminal_resize', { id, rows: terminal.rows, cols: terminal.cols }); });
    resize.observe(box.current!);
    const input = terminal.onData(text => { if (id) void invoke('terminal_write', { id, text }).catch(e => setError(String(e))); });
    void (async () => {
      unlisten = await listen<{ id: string; text: string }>('terminal-output', event => {
        if (!id) early.push(event.payload);
        else if (event.payload.id === id) terminal.write(event.payload.text);
      });
      if (disposed) { unlisten(); return; }
      id = await invoke<string>('terminal_open', { kind, agentId: agentId ?? null, assignmentId: assignmentId ?? null });
      if (disposed) { await invoke('terminal_close', { id }); return; }
      for (const o of early) if (o.id === id) terminal.write(o.text);
      early.length = 0;
