export function git(cwd: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', env: { ...process.env, GIT_AUTHOR_NAME: 't', GIT_AUTHOR_EMAIL: 't@example.com', GIT_COMMITTER_NAME: 't', GIT_COMMITTER_EMAIL: 't@example.com' } }).trim();
}

/** A fresh git repo seeded from examples/sample-repo with main + integration branches. */
export function makeRepo(): string {
  const dir = tmpDir('repo');
  fs.cpSync(path.join(ROOT, 'examples', 'sample-repo'), dir, { recursive: true });
  git(dir, 'init', '-q', '-b', 'main');
  git(dir, 'add', '-A');
  git(dir, 'commit', '-q', '-m', 'initial');
  git(dir, 'branch', 'integration');
  return dir;
}

export function makeConfig(repo: string, over: Record<string, unknown> = {}): ControlCenterConfig {
  return parseConfig({
    project: { name: 'sample', repo, integration_branch: 'integration', protected_branches: ['main'], checks: { test: 'node --test' } },
    tracker: { type: 'local' },
    policies: { stall: { no_event_minutes: 10, approval_pending_minutes: 15 }, quality_floor: {} },
    graphify:{enabled:false},
    agents: [
      { id: 'claude', name: 'Claude Code', role: 'engineer', adapter: 'claude-headless', binary: path.join(FAKE_BIN, 'claude'), model: 'newest', model_family: 'opus', effort: 'high' },
      { id: 'codex', name: 'Codex', role: 'engineer', adapter: 'codex-cli', binary: path.join(FAKE_BIN, 'codex'), model: 'newest', effort: 'high' },
      { id: 'cursor', name: 'Cursor', role: 'engineer', adapter: 'cursor-agent-cli', binary: path.join(FAKE_BIN, 'cursor-agent'), model: 'newest', model_family: 'claude-opus', effort: 'high' },
      { id: 'ag', name: 'Antigravity', role: 'engineer', adapter: 'relay' },
    ],
    ...over,
  });
}

export interface Harness {
  d: Daemon;
  url: string;
  dataDir: string;
  close(): Promise<void>;
}

export async function startDaemon(config: ControlCenterConfig, o: Partial<DaemonOptions> & { dataDir?: string; server?: boolean } = {}): Promise<Harness> {
  const dataDir = o.dataDir ?? tmpDir('data');
  const d = new Daemon({ config, dataDir, allowTempDataDir: true, rulesTickMs: 3_600_000, outboxTickMs: 100, supervisorPollMs: 50, ...o });
  d.rules.retryDelayMs = 0;
  d.rules.connectivity = async () => true;
  let close = async () => {};
  let url = '';
  if (o.server !== false) {
    const srv = await createServer(d, { port: 0 });
    url = srv.url;
    close = async () => {
      await srv.app.close();
    };
  }
  await d.start();
  await d.context.answer.refresh(false);
  return {
    d,
    url,
    dataDir,
    async close() {
      await d.setKillSwitch(true).catch(() => undefined);
      await close();
      await d.shutdown();
    },
  };
}

export async function waitFor<T>(fn: () => T | null | undefined | false, ms = 20_000, label = 'condition'): Promise<T> {
  const end = Date.now() + ms;
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() > end) throw new Error(`timed out waiting for ${label}`);
    await new Promise((r) => setTimeout(r, 50));
  }
}

// SPDX-License-Identifier: Apache-2.0
// Onboarding wizard data: installed vendor CLIs (configured or not), their versions and pinning,
// plus each configured agent's login state, billing mode and models.
import type { BinaryInfo } from '@acc/core';
import { chooseBinary, detectBinaries, newerCandidate } from './adapters/agents/detect.ts';
import { VENDOR_ADAPTERS } from './adapters/agents/index.ts';
import type { Daemon } from './daemon.ts';

export interface DetectedVendor {
  adapter: string;
  displayName: string;
  installUrl: string;
  loginHint: string;
  candidates: BinaryInfo[];
  pinned: BinaryInfo | null;
  newer: BinaryInfo | null;
  configuredAgents: string[];
}

export async function detectVendors(configured: { adapter: string; id: string }[]): Promise<DetectedVendor[]> {
  const out: DetectedVendor[] = [];
  for (const a of Object.values(VENDOR_ADAPTERS)) {
    if (a.binaryNames.length === 0) continue;
    const candidates = await detectBinaries(a);
    const pinned = chooseBinary(candidates);
    out.push({
      adapter: a.type,
      displayName: a.displayName,
      installUrl: a.installUrl,
      loginHint: a.loginHint,
      candidates,
      pinned,
      newer: newerCandidate(pinned, candidates),
      configuredAgents: configured.filter((c) => c.adapter === a.type).map((c) => c.id),
    });
  }
  return out;
}

export async function onboardingReport(d: Daemon) {
  const vendors = await detectVendors(Object.values(d.state.agents).map((a) => ({ adapter: a.config.adapter, id: a.id })));
  const agents = Object.values(d.state.agents).map((a) => {
    const adapter = VENDOR_ADAPTERS[a.config.adapter];
    return {
      id: a.id,
      name: a.config.name,
      subscription: a.config.subscription ?? null,
      role: a.config.role,
      mode: a.config.mode,
      adapter: a.config.adapter,
      displayName: adapter.displayName,
      installUrl: adapter.installUrl,
      loginHint: adapter.loginHint,
      capabilities: adapter.capabilities,
      auth: a.auth,
      billing: a.billing,
      meteredOptIn: a.config.metered_opt_in,
      binary: a.binary,
      binaryCandidates: a.binaryCandidates,
      models: a.models,
      usage: a.usage,
      probedAt: a.probedAt,
    };
  });
  return { vendors, agents, tracker: { type: d.tracker.type, target: d.tracker.target, live: d.tracker.live } };
}

