    frameworks: found.frameworks,
    packageManager: found.pm,
    checks: found.checks,
    compose,
    dockerfiles: found.dockerfiles,
    config: git.state === 'not_git' || git.state === 'not_root' ? { existing: null, bound: null, error: null } : existingConfig(resolved),
