  warnings: string[];
}

const SYSTEM_ROOTS = ['/System', '/Library', '/Applications', '/usr', '/bin', '/sbin', '/etc', '/private/etc', '/private/var/db', '/private/var/root', '/opt/homebrew', '/dev', '/cores'];

function real(p: string): string {
