export function suggestName(dir: string, pkgName: string | null): string {
  const base = (pkgName?.split('/').pop() ?? path.basename(dir)).toLowerCase().replace(/[^a-z0-9_.-]+/g, '-').replace(/^[^a-z0-9]+|-+$/g, '');
