      console.log('kill switch released');
      return;
    }
    case 'context': {
      const sub = argv[1];
      if (sub === 'sync') {
        const r = await api('/api/context/sync', { method: 'POST', body: '{}' });
        const g = await api('/api/context/graph/rebuild', { method: 'POST', body: '{}' });
