        assert_eq!(reg.get(&a).unwrap().name, "renamed");
        assert_eq!(reg.get(&a).unwrap().added_at, 1);
        reg.activate(&a).unwrap();
        reg.set_running(&a, true);
        assert!(reg.remove(&a).is_err());
