    if fs::File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut bytes)).is_err() {
        bytes.copy_from_slice(&Sha256::digest(format!("{:?}{}", Instant::now(), std::process::id()).as_bytes())[..16]);
    }
