// SPDX-License-Identifier: Apache-2.0
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
mod terminal;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{fs, path::PathBuf, process::{Child, Command, Stdio}, sync::Mutex, time::{Duration, Instant}};
use sha2::{Digest, Sha256};
use tauri::{Manager, State};

#[derive(Clone)]
struct Connection { url: String, token: String }
struct Desktop { connection: Mutex<Option<Connection>>, engine: Mutex<Option<Child>>, terminals: terminal::Terminals }
#[derive(Serialize)]
struct Bootstrap { websocket: String, mode: String }
#[derive(Deserialize)]
struct Info { url: String }

fn connection(state: &Desktop) -> Result<Connection, String> { state.connection.lock().map_err(|_| "State unavailable")?.clone().ok_or("Daemon not connected".into()) }
fn api_path(p: &str) -> Result<(), String> {
    if !p.starts_with("/api/") || p.contains("..") || p.contains(['\\', '#', '\r', '\n']) || p.starts_with("/api/mcp/") { return Err("Invalid daemon API path".into()); }
    Ok(())
}
async fn request(c: &Connection, path: &str, method: &str, body: Option<Value>) -> Result<Value, String> {
    api_path(path)?;
    let method = match method { "GET" => reqwest::Method::GET, "POST" => reqwest::Method::POST, "PATCH" => reqwest::Method::PATCH, "DELETE" => reqwest::Method::DELETE, _ => return Err("Method not supported".into()) };
    let mut r = reqwest::Client::new().request(method, format!("{}{}", c.url, path)).bearer_auth(&c.token).timeout(Duration::from_secs(65));
    if let Some(b) = body { r = r.json(&b); }
    let response = r.send().await.map_err(|e| e.to_string())?;
    let status = response.status();
    let text = response.text().await.map_err(|e| e.to_string())?;
    let value: Value = serde_json::from_str(&text).unwrap_or(Value::String(text));
    if !status.is_success() { return Err(value.get("error").and_then(Value::as_str).unwrap_or("Daemon request failed").to_string()); }
    Ok(value)
}
fn engine_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    if let Ok(root) = std::env::var("ACC_ENGINE_ROOT") { return Ok(PathBuf::from(root)); }
    let archive = app.path().resource_dir().map_err(|e| e.to_string())?.join("resources/engine.tar.gz");
    if archive.is_file() {
        let digest = Sha256::digest(fs::read(&archive).map_err(|e| e.to_string())?);
        let destination = app.path().app_data_dir().map_err(|e| e.to_string())?.join("runtimes").join(format!("{:x}", digest));
        if !destination.join("ready").exists() {
            fs::create_dir_all(&destination).map_err(|e| e.to_string())?;
            let status = Command::new("/usr/bin/tar").arg("xzf").arg(&archive).arg("-C").arg(&destination).status().map_err(|e| e.to_string())?;
            if !status.success() { return Err("Could not unpack bundled engine".into()); }
            fs::write(destination.join("ready"), b"ok").map_err(|e| e.to_string())?;
        }
        return Ok(destination.join("engine"));
    }
    // Dev uses the same prepared bundle as a packaged app.
    Ok(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("resources/engine"))
}
fn project_state(data: &std::path::Path, config: Option<&str>) -> PathBuf {
    match config {
        Some(p) => {
            let p = fs::canonicalize(p.trim()).unwrap_or_else(|_| PathBuf::from(p.trim()));
            let digest = Sha256::digest(p.to_string_lossy().as_bytes());
            data.join("projects").join(format!("{:x}", digest)).join("state")
        }
        None => data.join("demo/state"),
    }
}
#[tauri::command]
async fn desktop_bootstrap(app: tauri::AppHandle, state: State<'_, Desktop>) -> Result<Bootstrap, String> {
    let mode;
    if state.connection.lock().map_err(|_| "State unavailable")?.is_none() {
        let root = engine_root(&app)?;
        let data = app.path().app_data_dir().map_err(|e| e.to_string())?;
        fs::create_dir_all(&data).map_err(|e| e.to_string())?;
        let config = std::env::var("ACC_CONFIG").ok().or_else(|| fs::read_to_string(data.join("selected-config")).ok());
        mode = if config.is_some() { "project" } else { "offline-demo" };
        let runtime = root.join("runtime/node");
        if !runtime.is_file() { return Err("Runtime not prepared. Run pnpm desktop:prepare before launching.".into()); }
        let log = fs::OpenOptions::new().create(true).append(true).open(data.join("daemon.log")).map_err(|e| e.to_string())?;
        let daemon_data = project_state(&data, config.as_deref());
        let info_path = daemon_data.join("daemon.json");
        // The app owns this daemon; stale endpoint files from an earlier crash are never trusted.
        let _ = fs::remove_file(&info_path);
        let mut command = Command::new(runtime);
        command.current_dir(&root).env("ACC_DATA_DIR", &daemon_data).env("ACC_PORT", "0").env("ACC_DESKTOP", "1")
            .env("PATH", format!("{}:/opt/homebrew/bin:/usr/local/bin:{}/.local/bin:{}", root.join("runtime").display(), std::env::var("HOME").unwrap_or_default(), std::env::var("PATH").unwrap_or_default()))
            .stdin(Stdio::null()).stdout(Stdio::from(log.try_clone().map_err(|e| e.to_string())?)).stderr(Stdio::from(log));
        if let Some(config) = config { command.args(["packages/daemon/src/cli.ts", "daemon", "--config", config.trim(), "--port", "0"]); }
        else { command.arg("scripts/demo.mjs").env("ACC_DEMO_DIR", data.join("demo")); }
        let child = command.spawn().map_err(|e| e.to_string())?;
        *state.engine.lock().map_err(|_| "State unavailable")? = Some(child);
        let start = Instant::now();
        let info = loop {
            if let Ok(raw) = fs::read_to_string(&info_path) { if let Ok(i) = serde_json::from_str::<Info>(&raw) { break i; } }
            if state.engine.lock().map_err(|_| "State unavailable")?.as_mut().is_some_and(|child| child.try_wait().ok().flatten().is_some()) {
                return Err(format!("Daemon exited during startup. See {}", data.join("daemon.log").display()));
            }
            if start.elapsed() > Duration::from_secs(25) { return Err(format!("Daemon startup timed out. See {}", data.join("daemon.log").display())); }
            tokio_sleep().await;
        };
        let parsed = reqwest::Url::parse(&info.url).map_err(|e| e.to_string())?;
        if parsed.scheme() != "http" || parsed.host_str() != Some("127.0.0.1") { return Err("Daemon must bind to loopback".into()); }
        let token = fs::read_to_string(daemon_data.join("secrets/install-token")).map_err(|e| e.to_string())?;
        *state.connection.lock().map_err(|_| "State unavailable")? = Some(Connection { url: info.url, token: token.trim().into() });
    } else { mode = "connected"; }
    let c = connection(&state)?;
    let ticket = request(&c, "/api/auth/ws-ticket", "POST", Some(json!({}))).await?;
    Ok(Bootstrap { websocket: format!("{}/ws?ticket={}", c.url.replacen("http:", "ws:", 1), ticket["ticket"].as_str().ok_or("No ticket")?), mode: mode.into() })
}
async fn tokio_sleep() { tauri::async_runtime::spawn_blocking(|| std::thread::sleep(Duration::from_millis(100))).await.ok(); }
#[tauri::command]
async fn daemon_request(state: State<'_, Desktop>, path: String, method: String, body: Option<Value>) -> Result<Value, String> {
    request(&connection(&state)?, &path, &method, body).await
}
#[tauri::command]
async fn choose_project(app: tauri::AppHandle, state: State<'_, Desktop>) -> Result<String, String> {
    #[cfg(target_os = "macos")]
    let out = Command::new("osascript").args(["-e", "POSIX path of (choose file with prompt \"Choose control-center.yaml\")"]).output().map_err(|e| e.to_string())?;
    #[cfg(not(target_os = "macos"))]
    return Err("Project picker currently supports macOS".into());
    #[cfg(target_os = "macos")]
    {
        if !out.status.success() { return Err("Project selection canceled".into()); }
        let selected = String::from_utf8_lossy(&out.stdout).trim().to_string();
        let p = PathBuf::from(&selected);
        if !p.is_file() || !matches!(p.extension().and_then(|x| x.to_str()), Some("yaml" | "yml")) { return Err("Choose a YAML project configuration".into()); }
        if let Ok(c) = connection(&state) {
            let live = request(&c, "/api/state", "GET", None).await?;
            if live["state"]["runs"].as_object().is_some_and(|runs| runs.values().any(|r| r["endedAt"].is_null())) { return Err("Stop active runs before switching projects".into()); }
            let _ = request(&c, "/api/desktop/shutdown", "POST", Some(json!({}))).await;
        }
        state.terminals.close_all();
        let data = app.path().app_data_dir().map_err(|e| e.to_string())?;
        fs::write(data.join("selected-config"), &selected).map_err(|e| e.to_string())?;
        *state.connection.lock().map_err(|_| "State unavailable")? = None;
        Ok(selected)
    }
}
#[tauri::command]
async fn choose_vault() -> Result<String, String> {
    #[cfg(target_os = "macos")]
    {
        let out = tauri::async_runtime::spawn_blocking(|| Command::new("osascript").args(["-e", "POSIX path of (choose folder with prompt \"Choose the markdown or Obsidian vault for One Connect\")"]).output()).await.map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
        if !out.status.success() { return Err("Folder selection canceled".into()); }
        Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
    }
    #[cfg(not(target_os = "macos"))]
    { Err("Folder picker currently supports macOS".into()) }
}
fn main() {
    let app = tauri::Builder::default()
        .manage(Desktop { connection: Mutex::new(None), engine: Mutex::new(None), terminals: terminal::Terminals::default() })
        .invoke_handler(tauri::generate_handler![desktop_bootstrap, daemon_request, choose_project, choose_vault, terminal::terminal_open, terminal::terminal_write, terminal::terminal_resize, terminal::terminal_close])
        .setup(|app| {
            use tauri::menu::{Menu, MenuItem};
            let show = MenuItem::with_id(app, "show", "Show dashboard", true, None::<&str>)?;
            let quit = MenuItem::with_id(app, "quit", "Quit One Connect", true, None::<&str>)?;
            let menu = Menu::with_items(app, &[&show, &quit])?;
            let mut tray = tauri::tray::TrayIconBuilder::new().menu(&menu).tooltip("One Connect")
                .on_menu_event(|app, event| match event.id.as_ref() { "show" => { if let Some(w) = app.get_webview_window("main") { let _ = w.show(); let _ = w.set_focus(); } }, "quit" => app.exit(0), _ => {} });
            if let Some(icon) = app.default_window_icon() { tray = tray.icon(icon.clone()); }
            tray.build(app)?;
            Ok(())
        })
        .on_window_event(|window, event| if let tauri::WindowEvent::CloseRequested { api, .. } = event { api.prevent_close(); let _ = window.hide(); })
        .build(tauri::generate_context!()).expect("Desktop application could not start");
    app.run(|app, event| if let tauri::RunEvent::Exit = event {
        let state = app.state::<Desktop>();
        state.terminals.close_all();
        if let Ok(c) = connection(&state) {
            let _ = reqwest::blocking::Client::new().post(format!("{}/api/desktop/shutdown", c.url)).bearer_auth(c.token).timeout(Duration::from_secs(3)).json(&json!({})).send();
        }
    });
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test] fn proxy_paths_cannot_escape() {
        assert!(api_path("/api/state").is_ok());
        for p in ["https://evil.test", "/api/../secrets", "/api/mcp/run", "/api/\\evil", "/not-api"] { assert!(api_path(p).is_err()); }
    }
    #[test] fn project_state_is_isolated_and_stable() {
        let data = std::path::Path::new("/tmp/acc-data");
        assert_eq!(project_state(data, None), data.join("demo/state"));
        assert_eq!(project_state(data, Some("/tmp/one.yaml")), project_state(data, Some("/tmp/one.yaml\n")));
        assert_ne!(project_state(data, Some("/tmp/one.yaml")), project_state(data, Some("/tmp/two.yaml")));
    }
}

