        assert!(matches!(ensure_connection(&state, &"b".repeat(64)), Err(e) if e.contains("stopped")));
        for (_, mut e) in lock(&state.engines).unwrap().drain() { let _ = e.child.kill(); let _ = e.child.wait(); }
    }
}

