        terminal.write(back.text);
        after = back.seq;
      } else {
        id = await invoke<string>('terminal_open', { project, kind, agentId: agentId ?? null, assignmentId: assignmentId ?? null });
        if (disposed) return;
        sessionCallback.current?.(id);
      }
      attached = true;
      for (const o of early) show(o);
      early.length = 0;
