// SPDX-License-Identifier: Apache-2.0
import { lazy, Suspense, useEffect, useState } from 'react';
import type { ControlState, Decision } from '@acc/core';
const NativeTerminal = lazy(() => import('../components/NativeTerminal').then(m => ({ default: m.NativeTerminal }))); 
import { Badge, ErrorLine, useAction } from '../components/common';
import { api, post } from '../lib/api';
import { isDesktop } from '../lib/desktop';
interface Containers { available: boolean; project: string; error: string | null; containers: { ID: string; Names: string; State: string; Status: string; Image: string }[] }
export function Workspace({ state }: { state: ControlState }) {
  const [mode, setMode] = useState<'shell' | 'login'>('shell');
  const loginAgents = Object.values(state.agents).filter(a => ['codex-cli','claude-headless','cursor-agent-cli'].includes(a.config.adapter));
  const [agent, setAgent] = useState(loginAgents[0]?.id ?? '');
  const [assignment, setAssignment] = useState('');
  const [open, setOpen] = useState(false);
  const [docker, setDocker] = useState<Containers | null>(null);
  const [container, setContainer] = useState('');
  const [logs, setLogs] = useState('');
  const [decision, setDecision] = useState<Decision | null>(null);
  const [result, setResult] = useState('');
  const { busy, error, run } = useAction();
  const refresh = () => api<Containers>('/api/docker').then(setDocker);
  useEffect(() => { void refresh().catch(() => {}); const timer = setInterval(() => void refresh().catch(() => {}), 5000); return () => clearInterval(timer); }, []);
  useEffect(() => { if (!container) return; const load = () => api<{ text: string }>(`/api/docker/${container}/logs`).then(r => setLogs(r.text)).catch(e => setLogs(e.message)); void load(); const timer = setInterval(load, 3000); return () => clearInterval(timer); }, [container]);
  return <div className="page col" style={{ gap: 18 }}><h1 style={{ fontSize: 20 }}>Workspace</h1>
    <section className="card"><div className="card-h"><h2>Terminal</h2><span className="spacer" /><span className="small faint">Project shell and vendor logins</span></div><div className="card-b col">
      {!isDesktop ? <p className="muted">The native terminal is available in the Mac app. Agent transcripts and chat remain available in this browser.</p> : <>
        <div className="row wrap"><select aria-label="Terminal mode" value={mode} disabled={open} onChange={e => setMode(e.target.value as 'shell' | 'login')}><option value="shell">Project shell</option><option value="login">Sign in to agent</option></select>
          {mode === 'login' ? <select aria-label="Login agent" disabled={open} value={agent} onChange={e => setAgent(e.target.value)}>{loginAgents.map(a => <option key={a.id} value={a.id}>{a.config.name}</option>)}</select> : <select aria-label="Working directory" disabled={open} value={assignment} onChange={e => setAssignment(e.target.value)}><option value="">Project repository</option>{Object.values(state.assignments).filter(a => a.worktree).map(a => <option key={a.id} value={a.id}>{state.workItems[a.workItemId]?.key} · {a.agentId}</option>)}</select>}
          <button className="btn primary" disabled={!open && mode === 'login' && !loginAgents.length} onClick={() => setOpen(!open)}>{open ? 'Close terminal' : 'Open terminal'}</button></div>
        {open && <Suspense fallback={<p>Opening terminal…</p>}><NativeTerminal kind={mode} agentId={agent} assignmentId={assignment || undefined} /></Suspense>}
      </>}
    </div></section>
    <section className="card"><div className="card-h"><h2>Project containers</h2><Badge tone={docker?.available ? 'ok' : 'warn'}>{docker?.available ? docker.project : 'Docker unavailable'}</Badge><span className="spacer" /><button className="btn sm" onClick={() => void run(refresh)}>Refresh</button></div><div className="card-b col">
      <p className="small muted">Only containers labelled for this Compose project appear here. Start, stop and restart each require your approval. Images are never pulled.</p>
      {docker?.error && <p className="small muted">{docker.error}</p>}
      {docker?.available && !docker.containers.length && <p className="faint">No containers in this project. Set <code>project.docker_project</code> to its Compose project name.</p>}
      {docker?.containers.map(c => <div className="row wrap" key={c.ID}><b>{c.Names}</b><Badge tone={c.State === 'running' ? 'ok' : 'idle'}>{c.Status}</Badge><span className="small faint">{c.Image}</span><span className="spacer" /><button className="btn sm" onClick={() => setContainer(c.ID)}>Logs</button>{['start','stop','restart'].map(action => <button key={action} className="btn sm" disabled={busy || Boolean(decision)} onClick={() => void run(async () => { setResult(''); setDecision((await post<{ decision: Decision }>(`/api/docker/${c.ID}/request`, { action })).decision); })}>{action}</button>)}</div>)}
