import { api, ApiError } from './api';

export type Conn = 'connecting' | 'live' | 'offline' | 'unauthorized';

interface Meta {
  demo: boolean;
  tracker: { type: string; target: string; live: boolean } | null;
  outbox: { pending: number; failing: number } | null;
}

type Listener = () => void;

