// ---- gated actions -----------------------------------------------------------------------

private bindingScope(services: string[]): string[] {
  const known = this.declaredServices();
  return services.length ? services : known;
}

/** One read of every Compose file and scoped Dockerfile; used for digesting and snapshotting. */
private readComposeBinding(action: ComposeAction, serviceNames: string[]): ComposeBinding {
  const repo = fs.realpathSync(this.repo);
  const { project, generated } = this.composeFiles();
  const files: ComposeBinding['files'] = [];
  for (const cf of [project, generated]) {
    if (!cf) continue;
    const content = readBounded(cf.file);
    if (content === null) throw new EnvironmentError(`${path.basename(cf.file)} is missing, a symlink or larger than 256 KiB`, 409);
    files.push({ path: cf.file, sha256: sha(content), content });
  }
  const scope = this.bindingScope(serviceNames);
  const dockerfiles: ComposeBinding['dockerfiles'] = [];
  const seenDockerfiles = new Set<string>();
  const serviceSettings: Record<string, unknown> = {};
  for (const cf of [project, generated]) {
    if (!cf) continue;
    const doc = YAML.parse(files.find(f => f.path === cf.file)!.content, { maxAliasCount: 50 }) as { services?: Record<string, unknown> } | null;
    for (const name of scope) {
      const svc = doc?.services?.[name];
      if (svc !== undefined) serviceSettings[name] = svc;
      const raw = svc as Record<string, unknown> | undefined;
      if (!raw?.build) continue;
      const ctx = typeof raw.build === 'string' ? raw.build : String((raw.build as { context?: string }).context ?? '.');
      const df = typeof raw.build === 'object' && raw.build && typeof (raw.build as { dockerfile?: string }).dockerfile === 'string'
        ? (raw.build as { dockerfile: string }).dockerfile : 'Dockerfile';
      const dockerfile = path.resolve(repo, ctx, df);
      if (seenDockerfiles.has(dockerfile)) continue;
      seenDockerfiles.add(dockerfile);
      const text = readBounded(dockerfile);
      if (text === null) throw new EnvironmentError(`Dockerfile ${path.relative(repo, dockerfile)} is missing, a symlink or larger than 256 KiB`, 409);
      dockerfiles.push({ path: dockerfile, sha256: sha(text) });
    }
  }
  return { project: this.project, repo, action, services: [...serviceNames], files, dockerfiles, serviceSettings };
}

private digestOf(binding: ComposeBinding): string {
  return sha(JSON.stringify({
    project: binding.project,
    repo: binding.repo,
    action: binding.action,
    services: binding.services,
    files: binding.files.map(f => ({ path: f.path, sha256: f.sha256 })),
    dockerfiles: binding.dockerfiles,
    serviceSettings: binding.serviceSettings,
  }));
}

/** Write verified Compose bytes to a private snapshot directory; returned paths feed `-f`. */
private materializeSnapshot(binding: ComposeBinding, decisionId: string): { dir: string; composeFiles: string[] } {
  const dir = path.join(this.files.dir, 'approval-snapshots', decisionId);
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  const composeFiles = binding.files.map((f, i) => {
    const dest = path.join(dir, `${i}-${path.basename(f.path)}`);
    writePrivate(dest, f.content);
    return dest;
  });
  return { dir, composeFiles };
}

private argvForSnapshot(composeFiles: string[], action: ComposeAction, services: string[]): string[] {
  const tail: Record<ComposeAction, string[]> = { up: ['up', '--detach', '--no-build', '--pull', 'never'], stop: ['stop'], restart: ['restart'], build: ['build'], pull: ['pull'], down: ['down'] };
  return ['docker', 'compose', '--project-name', this.project, '--project-directory', fs.realpathSync(this.repo), ...composeFiles.flatMap(f => ['-f', f]), ...tail[action], ...services];
}

