    if (args[0] === 'compose' && args[1] === 'version') return ok('2.40.0\n');
    if (args[0] === 'ps' && args.includes('-a')) {
      const label = args[args.indexOf('--filter') + 1].split('=')[2];
      return ok(this.containers.filter(c => c.project === label).map(c => c.id).join('\n'));
