    await expect(env.resolve(req.decision!.id, 'approve', 'f'.repeat(64))).rejects.toThrow(/different command/);
    expect(mutations()).toEqual([]);
    const ran = await env.resolve(req.decision!.id, 'approve', req.digest!);
